import{_ as e,o as r,c as t,a0 as i}from"./chunks/framework.BXmxXpv-.js";const _=JSON.parse('{"title":"研究方向","description":"电子科技大学智能计算系统实验室研究方向，涵盖物联网边端智能、具身智能感知、集群协同通信和智能信息处理。","frontmatter":{"title":"研究方向","description":"电子科技大学智能计算系统实验室研究方向，涵盖物联网边端智能、具身智能感知、集群协同通信和智能信息处理。"},"headers":[],"relativePath":"zh/research.md","filePath":"zh/research.md","lastUpdated":1789370207000}'),h={name:"zh/research.md"};function l(o,a,n,s,c,d){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="研究方向" tabindex="-1">研究方向 <a class="header-anchor" href="#研究方向" aria-label="Permalink to &quot;研究方向&quot;">​</a></h1><p>智能计算系统实验室关注智能计算系统如何感知物理世界、实现可靠通信并支撑智能决策。实验室围绕计算体系、无线系统、智能感知和数据驱动方法形成四个相互关联的研究方向。</p><h2 id="物联网边端体系与智能计算" tabindex="-1">物联网边端体系与智能计算 <a class="header-anchor" href="#物联网边端体系与智能计算" aria-label="Permalink to &quot;物联网边端体系与智能计算&quot;">​</a></h2><p>研究面向具身智能的轻量化边缘智能算法与芯片设计、端—边—云协同计算架构与任务卸载策略，以及移动分析与机器学习在边缘端的应用。</p><h2 id="具身智能感知与交互" tabindex="-1">具身智能感知与交互 <a class="header-anchor" href="#具身智能感知与交互" aria-label="Permalink to &quot;具身智能感知与交互&quot;">​</a></h2><p>研究物理世界智能化感知、图像与视觉信息计算的认知机理，以及连接物理信号与智能交互的无源无线感知系统。</p><h2 id="集群协同智能与通信" tabindex="-1">集群协同智能与通信 <a class="header-anchor" href="#集群协同智能与通信" aria-label="Permalink to &quot;集群协同智能与通信&quot;">​</a></h2><p>研究面向集群协同的通信技术、分布式智能与协同决策、无线系统及网络安全。</p><h2 id="智能信息处理与系统应用" tabindex="-1">智能信息处理与系统应用 <a class="header-anchor" href="#智能信息处理与系统应用" aria-label="Permalink to &quot;智能信息处理与系统应用&quot;">​</a></h2><p>研究数据挖掘、推荐系统和智能数据分析方法，并开展原型系统与应用示范。</p><h2 id="相关信息" tabindex="-1">相关信息 <a class="header-anchor" href="#相关信息" aria-label="Permalink to &quot;相关信息&quot;">​</a></h2><ul><li><a href="/zh/projects">代表性科研项目</a></li><li><a href="/zh/publication">精选科研论文</a></li><li><a href="/zh/people">实验室成员</a></li><li><a href="/zh/contact">联系我们</a></li></ul>',12)])])}const u=e(h,[["render",l]]);export{_ as __pageData,u as default};
